package com.secman.mcp.tools

import com.secman.domain.Asset
import com.secman.domain.McpOperation
import com.secman.domain.ProductClass
import com.secman.domain.Vulnerability
import com.secman.dto.mcp.McpExecutionContext
import com.secman.repository.AssetRepository
import com.secman.repository.VulnerabilityRepository
import com.secman.service.VulnerabilityExceptionService
import io.micronaut.data.model.Pageable
import jakarta.inject.Inject
import jakarta.inject.Singleton
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * MCP tool for retrieving vulnerability data with filtering and pagination.
 * Feature 006: MCP Tools for Asset Inventory, Scans, Vulnerabilities, and Products
 * Feature 052: MCP Access Control - Filters results based on delegated user's accessible assets
 */
@Singleton
open class GetVulnerabilitiesTool(
    @Inject private val vulnerabilityRepository: VulnerabilityRepository,
    @Inject private val vulnerabilityExceptionService: VulnerabilityExceptionService,
    @Inject private val assetRepository: AssetRepository
) : McpTool {

    override val name = "get_vulnerabilities"
    override val description = "Retrieve vulnerability data with optional filtering and pagination"
    override val operation = McpOperation.READ

    override val inputSchema = mapOf(
        "type" to "object",
        "properties" to mapOf(
            "page" to mapOf(
                "type" to "number",
                "description" to "Page number (0-indexed)",
                "minimum" to 0,
                "default" to 0
            ),
            "pageSize" to mapOf(
                "type" to "number",
                "description" to "Number of items per page (max 500)",
                "minimum" to 1,
                "maximum" to 500,
                "default" to 100
            ),
            "cveId" to mapOf(
                "type" to "string",
                "description" to "Filter by CVE ID (partial match, case-insensitive)"
            ),
            "severity" to mapOf(
                "type" to "array",
                "description" to "Filter by CVSS severity levels",
                "items" to mapOf("type" to "string"),
                "enum" to listOf("Critical", "High", "Medium", "Low", "Info")
            ),
            "assetId" to mapOf(
                "type" to "number",
                "description" to "Filter by asset ID"
            ),
            "startDate" to mapOf(
                "type" to "string",
                "description" to "Filter vulnerabilities scanned after this date (ISO-8601)",
                "format" to "date-time"
            ),
            "endDate" to mapOf(
                "type" to "string",
                "description" to "Filter vulnerabilities scanned before this date (ISO-8601)",
                "format" to "date-time"
            ),
            "includeExcepted" to mapOf(
                "type" to "boolean",
                "description" to "Include vulnerabilities that are covered by active exceptions (default: false). Set to true to see all vulnerabilities including excepted ones.",
                "default" to false
            ),
            "includeInstallerFindings" to mapOf(
                "type" to "boolean",
                "description" to "Include findings whose affected product is an installer or setup payload rather than deployed software (e.g. \"Chrome Installer\", \"Photon Setup\"). Default false, matching the web UI.",
                "default" to false
            )
        )
    )

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        val page = (arguments["page"] as? Number)?.toInt() ?: 0
        val pageSize = (arguments["pageSize"] as? Number)?.toInt() ?: 100
        val cveIdFilter = arguments["cveId"] as? String
        val severityFilter = arguments["severity"] as? List<*>
        val assetIdFilter = (arguments["assetId"] as? Number)?.toLong()
        val startDateStr = arguments["startDate"] as? String
        val endDateStr = arguments["endDate"] as? String
        val includeExcepted = arguments["includeExcepted"] as? Boolean ?: false
        val includeInstallerFindings = arguments["includeInstallerFindings"] as? Boolean ?: false

        // Validate parameters
        if (pageSize < 1 || pageSize > 500) {
            return McpToolResult.error("INVALID_PAGE_SIZE", "Page size must be between 1 and 500")
        }
        if (page < 0) {
            return McpToolResult.error("INVALID_PAGE", "Page number must be 0 or greater")
        }

        try {
            val pageable = Pageable.from(page, pageSize)

            // Parse dates if provided
            val startDate = startDateStr?.let { LocalDateTime.parse(it, DateTimeFormatter.ISO_DATE_TIME) }
            val endDate = endDateStr?.let { LocalDateTime.parse(it, DateTimeFormatter.ISO_DATE_TIME) }

            // Get accessible asset IDs for access control filtering
            val accessibleIds = context.getFilterableAssetIds()

            // If delegation is active and user has no accessible assets, return empty result
            if (accessibleIds != null && accessibleIds.isEmpty()) {
                return McpToolResult.success(mapOf(
                    "vulnerabilities" to emptyList<Map<String, Any?>>(),
                    "total" to 0,
                    "page" to page,
                    "pageSize" to pageSize,
                    "totalPages" to 0
                ))
            }

            // If filtering by specific asset, check access first
            if (assetIdFilter != null && !context.canAccessAsset(assetIdFilter)) {
                return McpToolResult.error("ASSET_NOT_FOUND", "Asset with ID $assetIdFilter not found")
            }

            // Query based on filters (priority order), applying access control where needed
            val resultPage = when {
                // Every branch below applies the access filter AND the paging in SQL. They used to
                // read all matching rows with Pageable.UNPAGED — which emits no LIMIT — and slice
                // the result in Kotlin, so cost grew with the table rather than the page size.
                // Unlike the no-filter branch, those reads were unbounded for admins too.

                // CVE ID search with access control
                cveIdFilter != null -> {
                    if (accessibleIds != null) {
                        vulnerabilityRepository.findByAssetIdInAndVulnerabilityIdContainingIgnoreCase(
                            accessibleIds, cveIdFilter, pageable
                        )
                    } else {
                        vulnerabilityRepository.findByVulnerabilityIdContainingIgnoreCase(cveIdFilter, pageable)
                    }
                }

                // Asset-specific vulnerabilities (already access-checked above)
                assetIdFilter != null -> vulnerabilityRepository.findByAssetId(assetIdFilter, pageable)

                // Date range filter with access control
                startDate != null && endDate != null -> {
                    if (accessibleIds != null) {
                        vulnerabilityRepository.findByAssetIdInAndScanTimestampBetween(
                            accessibleIds, startDate, endDate, pageable
                        )
                    } else {
                        vulnerabilityRepository.findByScanTimestampBetween(startDate, endDate, pageable)
                    }
                }

                // Severity filter with access control
                severityFilter != null && severityFilter.isNotEmpty() -> {
                    val severities = severityFilter.mapNotNull { it as? String }
                    if (accessibleIds != null) {
                        vulnerabilityRepository.findByAssetIdInAndCvssSeverityIn(accessibleIds, severities, pageable)
                    } else {
                        vulnerabilityRepository.findByCvssSeverityIn(severities, pageable)
                    }
                }

                // No filters - get all with access control.
                // The access filter and the paging both run in SQL. Reading the table with
                // findAll() and filtering in Kotlin loaded every vulnerability row into heap
                // (1.1M entities against a 1 GB heap = OutOfMemoryError), and the cost grew
                // with the table rather than with the page size actually requested.
                else -> {
                    if (accessibleIds != null) {
                        vulnerabilityRepository.findByAssetIdIn(accessibleIds, pageable)
                    } else {
                        vulnerabilityRepository.findAll(pageable)
                    }
                }
            }

            // Eagerly hydrate the assets referenced by this page so we never touch
            // a Hibernate proxy outside of an active session. Proxy.id is safe to read
            // (stored on the proxy itself), but any other field would trigger lazy
            // initialization and fail with "no session".
            val assetIds = resultPage.content.mapNotNull { it.asset.id }.toSet()
            val assetsById: Map<Long, Asset> = if (assetIds.isEmpty()) {
                emptyMap()
            } else {
                assetRepository.findByIdIn(assetIds).associateBy { it.id!! }
            }

            // Filter out excepted vulnerabilities unless explicitly included
            val exceptionFiltered: List<Vulnerability> = if (!includeExcepted) {
                val activeExceptions = vulnerabilityExceptionService.getActiveExceptions()
                resultPage.content.filter { vuln ->
                    val asset = assetsById[vuln.asset.id] ?: return@filter false
                    activeExceptions.none { ex -> ex.matches(vuln, asset) }
                }
            } else {
                resultPage.content
            }

            // Installer/setup payload filter, reading the materialized class. Applied here rather
            // than in SQL because this tool's query branches are plain derived finders with no
            // shared WHERE fragment to extend; it therefore inherits the same post-pagination
            // caveat the exception filter above already has (`total` reflects the filtered page).
            // UNKNOWN reads as visible, exactly as it does in every SQL surface.
            val filteredContent: List<Vulnerability> = if (!includeInstallerFindings) {
                exceptionFiltered.filter { it.productClass != ProductClass.INSTALLER_ARTIFACT }
            } else {
                exceptionFiltered
            }

            // Map vulnerabilities to response format using hydrated assets
            val vulnerabilities = filteredContent.map { vuln ->
                val asset = assetsById[vuln.asset.id]
                mapOf(
                    "id" to vuln.id,
                    "assetId" to vuln.asset.id,
                    "assetName" to asset?.name,
                    "vulnerabilityId" to vuln.vulnerabilityId,
                    "cvssSeverity" to vuln.cvssSeverity,
                    "vulnerableProductVersions" to vuln.vulnerableProductVersions,
                    "daysOpen" to vuln.daysOpen,
                    "scanTimestamp" to vuln.scanTimestamp.toString(),
                    "createdAt" to vuln.createdAt?.toString()
                )
            }

            val response = mapOf(
                "vulnerabilities" to vulnerabilities,
                "total" to if (!includeExcepted || !includeInstallerFindings) vulnerabilities.size.toLong() else resultPage.totalSize,
                "page" to page,
                "pageSize" to pageSize,
                "totalPages" to resultPage.totalPages,
                "exceptedFiltered" to !includeExcepted,
                "installerFindingsFiltered" to !includeInstallerFindings
            )

            return McpToolResult.success(response)

        } catch (e: java.time.format.DateTimeParseException) {
            return McpToolResult.error("INVALID_DATE_FORMAT", "Date must be in ISO-8601 format: ${e.message}")
        } catch (e: Exception) {
            return McpToolResult.error("EXECUTION_ERROR", "Failed to retrieve vulnerabilities: ${e.message}")
        }
    }
}
package com.secman.mcp.tools

import com.secman.domain.Asset
import com.secman.domain.Vulnerability
import com.secman.dto.mcp.McpExecutionContext
import com.secman.repository.AssetRepository
import com.secman.repository.VulnerabilityRepository
import com.secman.service.VulnerabilityExceptionService
import io.micronaut.data.model.Page
import io.micronaut.data.model.Pageable
import io.mockk.every
import io.mockk.mockk
import io.mockk.verify
import kotlinx.coroutines.runBlocking
import org.assertj.core.api.Assertions.assertThat
import org.junit.jupiter.api.Test
import java.time.LocalDateTime

/**
 * Regression tests for the unbounded reads described on VulnerabilityRepository.findByAssetIdIn.
 *
 * The no-filter branch of this tool was fixed earlier; the CVE, date-range and severity branches
 * still read every matching row with Pageable.UNPAGED and sliced the result in Kotlin. UNPAGED
 * emits no LIMIT clause, so those branches scanned the multi-million-row vulnerability table into
 * heap — and unlike the no-filter branch they did so for admins as well as delegated users.
 *
 * This is the tool the extensions/ clients call, so it is the highest-exposure of the three.
 */
class GetVulnerabilitiesToolTest {

    private val vulnerabilityRepository = mockk<VulnerabilityRepository>()
    private val exceptionService = mockk<VulnerabilityExceptionService>()
    private val assetRepository = mockk<AssetRepository>()

    private val tool = GetVulnerabilitiesTool(vulnerabilityRepository, exceptionService, assetRepository)

    private val accessibleAsset = Asset(
        id = 1L, name = "web-01", type = "SERVER", ip = "10.0.0.1", owner = "alice"
    )

    private val vuln = Vulnerability(
        id = 1L,
        asset = Asset(id = 1L, name = "", type = "", owner = ""),
        vulnerabilityId = "CVE-2026-1",
        cvssSeverity = "High",
        scanTimestamp = LocalDateTime.now()
    )

    private fun ctx(accessibleIds: Set<Long>?) = mockk<McpExecutionContext>().also {
        every { it.getFilterableAssetIds() } returns accessibleIds
        every { it.canAccessAsset(any()) } returns true
    }

    private fun onePage(size: Int = 50) = Page.of(listOf(vuln), Pageable.from(0, size), 1L)

    /** Trap: stub every UNPAGED read so buggy code still "works" and the verify is what fails. */
    private fun stubUnpagedReads() {
        every {
            vulnerabilityRepository.findByVulnerabilityIdContainingIgnoreCase(any(), Pageable.UNPAGED)
        } returns Page.of(listOf(vuln), Pageable.UNPAGED, 1L)
        every {
            vulnerabilityRepository.findByScanTimestampBetween(any(), any(), Pageable.UNPAGED)
        } returns Page.of(listOf(vuln), Pageable.UNPAGED, 1L)
        every {
            vulnerabilityRepository.findByCvssSeverity(any(), Pageable.UNPAGED)
        } returns Page.of(listOf(vuln), Pageable.UNPAGED, 1L)
        every {
            vulnerabilityRepository.findByCvssSeverityIn(any(), Pageable.UNPAGED)
        } returns Page.of(listOf(vuln), Pageable.UNPAGED, 1L)
        every { assetRepository.findByIdIn(any()) } returns listOf(accessibleAsset)
        every { exceptionService.getActiveExceptions() } returns emptyList()
    }

    private fun assertNoUnpagedRead() {
        verify(exactly = 0) { vulnerabilityRepository.findByVulnerabilityIdContainingIgnoreCase(any(), Pageable.UNPAGED) }
        verify(exactly = 0) { vulnerabilityRepository.findByScanTimestampBetween(any(), any(), Pageable.UNPAGED) }
        verify(exactly = 0) { vulnerabilityRepository.findByCvssSeverity(any(), Pageable.UNPAGED) }
        verify(exactly = 0) { vulnerabilityRepository.findByCvssSeverityIn(any(), Pageable.UNPAGED) }
    }

    // ------------------------------------------------------------------ CVE filter

    @Test
    fun `cve search is paged in SQL for a restricted caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByAssetIdInAndVulnerabilityIdContainingIgnoreCase(setOf(1L), "CVE-2026", any())
        } returns onePage()

        val result = tool.execute(mapOf("cveId" to "CVE-2026", "pageSize" to 50), ctx(setOf(1L)))

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
        verify {
            vulnerabilityRepository.findByAssetIdInAndVulnerabilityIdContainingIgnoreCase(
                setOf(1L), "CVE-2026", match { it.size == 50 }
            )
        }
    }

    @Test
    fun `cve search is paged in SQL for an admin caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByVulnerabilityIdContainingIgnoreCase("CVE-2026", match<Pageable> { it != Pageable.UNPAGED })
        } returns onePage()

        val result = tool.execute(mapOf("cveId" to "CVE-2026", "pageSize" to 50), ctx(null))

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }

    // ------------------------------------------------------------------ date range

    @Test
    fun `date range is paged in SQL for a restricted caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByAssetIdInAndScanTimestampBetween(setOf(1L), any(), any(), any())
        } returns onePage()

        val result = tool.execute(
            mapOf(
                "startDate" to "2026-01-01T00:00:00",
                "endDate" to "2026-02-01T00:00:00",
                "pageSize" to 50
            ),
            ctx(setOf(1L))
        )

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
        verify {
            vulnerabilityRepository.findByAssetIdInAndScanTimestampBetween(
                setOf(1L), any(), any(), match { it.size == 50 }
            )
        }
    }

    @Test
    fun `date range is paged in SQL for an admin caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByScanTimestampBetween(any(), any(), match<Pageable> { it != Pageable.UNPAGED })
        } returns onePage()

        val result = tool.execute(
            mapOf(
                "startDate" to "2026-01-01T00:00:00",
                "endDate" to "2026-02-01T00:00:00",
                "pageSize" to 50
            ),
            ctx(null)
        )

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }

    // ------------------------------------------------------------------ severity

    @Test
    fun `single severity is paged in SQL for a restricted caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByAssetIdInAndCvssSeverityIn(setOf(1L), listOf("HIGH"), any())
        } returns onePage()

        val result = tool.execute(mapOf("severity" to listOf("HIGH"), "pageSize" to 50), ctx(setOf(1L)))

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }

    @Test
    fun `multiple severities are paged in SQL for a restricted caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByAssetIdInAndCvssSeverityIn(setOf(1L), listOf("CRITICAL", "HIGH"), any())
        } returns onePage()

        val result = tool.execute(
            mapOf("severity" to listOf("CRITICAL", "HIGH"), "pageSize" to 50),
            ctx(setOf(1L))
        )

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }

    @Test
    fun `severity is paged in SQL for an admin caller`() = runBlocking {
        stubUnpagedReads()
        every {
            vulnerabilityRepository.findByCvssSeverityIn(listOf("CRITICAL", "HIGH"), match<Pageable> { it != Pageable.UNPAGED })
        } returns onePage()

        val result = tool.execute(
            mapOf("severity" to listOf("CRITICAL", "HIGH"), "pageSize" to 50),
            ctx(null)
        )

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }

    // ------------------------------------------------------------------ untouched paths

    @Test
    fun `asset-scoped query keeps using the paged repository call`() = runBlocking {
        stubUnpagedReads()
        every { vulnerabilityRepository.findByAssetId(1L, any()) } returns onePage()

        val result = tool.execute(mapOf("assetId" to 1, "pageSize" to 50), ctx(setOf(1L)))

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
        verify { vulnerabilityRepository.findByAssetId(1L, match { it.size == 50 }) }
    }

    @Test
    fun `empty accessible set short-circuits without querying`() = runBlocking {
        stubUnpagedReads()

        val result = tool.execute(mapOf("pageSize" to 50), ctx(emptySet()))

        assertThat(result.isError).isFalse()
        assertNoUnpagedRead()
    }
}

