    val mode: String,
    val dryRun: Boolean,
    val onboarding: List<CliAccountOnboarding> = emptyList(),
    val riskAssessments: List<CliAccountRiskAssessment> = emptyList(),
    val ruleMatrix: CliOnboardingRuleMatrix? = null
)
