/**
 * AWS account onboarding configuration.
 *
 * ADMIN or SECCHAMPION — the island applies the visible gate and
 * `AccountOnboardingController` applies the real one. Reachable from the RISK MANAGEMENT
 * sidebar section rather than the ADMIN one, because that block is gated on `isAdmin` alone
 * and a SECCHAMPION would never see the link.
 */
import Layout from '../../layouts/Layout.astro';
import AccountOnboardingManager from '../../components/admin/AccountOnboardingManager';
---

<Layout title="Account Onboarding - SecMan">
  <div class="container-fluid py-4">
    <div class="d-flex justify-content-between align-items-center mb-4">
      <h2 class="mb-0">AWS Account Onboarding</h2>
      <a href="/admin" class="btn btn-secondary">
        <i class="bi bi-arrow-left me-2"></i>Back to Admin
      </a>
    </div>
    <AccountOnboardingManager client:load />
  </div>
</Layout>
 */
export function canAccessUseCaseManagement(roles: string[] | undefined): boolean {
  return isAdmin(roles) || isSecChampion(roles) || isReq(roles);
}

/**
 * Check if user can access AWS Account Onboarding configuration
 *
 * Rules:
 * - ADMIN can access
 * - SECCHAMPION can access
 *
 * Mirrors `@Secured("ADMIN", "SECCHAMPION")` on `AccountOnboardingController` — for reads *and*
 * writes, unlike Demand Classification which is read-both/write-ADMIN. Deciding which security
 * requirements apply to a cloud account is a security champion's job; routing every rule edit
 * through an ADMIN would make the feature unusable by the people who own it.
 *
 * This is the UI gate only. The controller annotation is the boundary (CLAUDE.md Principle 2).
 */
export function canAccessAccountOnboarding(roles: string[] | undefined): boolean {
  return isAdmin(roles) || isSecChampion(roles);

