/**
 * Public Layout
 *
 * Layout for public pages that don't require authentication.
 * Used for alignment review pages accessed via email token.
 */
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap-icons/font/bootstrap-icons.css';
import '../styles/theme.css';
import '../styles/bootstrap-overrides.css';

interface Props {
    title?: string;
}

const { title = "SecMan" } = Astro.props;
---

<!doctype html>
<html lang="en">
    <head>
        <meta charset="UTF-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1" />
        <link rel="icon" type="image/svg+xml" href="/favicon.svg" />
        <meta name="generator" content={Astro.generator} />
        <title>{title}</title>
        <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet" integrity="REDACTED" crossorigin="anonymous">
        <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">
    </head>
    <body class="bg-light">
        <slot />
        <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js" integrity="REDACTED" crossorigin="anonymous"></script>
    </body>
</html>
  const fetchAssessmentData = async () => {
    try {
      const response = await fetch(`/api/responses/assessment/${token}`);
      if (!response.ok) {
        if (response.status === 401) {
          throw new Error('Invalid or expired access link');
        }
        throw new Error('Failed to load assessment data');
      }

      const data: AssessmentData = await response.json();
      setAssessmentData(data);

      // Initialize responses with existing data
      const initialResponses: ResponseFormData = {};
      data.requirements.forEach(req => {
        const existingResponse = data.existingResponses.find(resp => resp.requirement.id === req.id);
        initialResponses[req.id] = {
          answer: existingResponse?.answer || '',
