import React, { useState, useEffect } from 'react';
import { parseServerDate, formatServerDateTime } from '../utils/dateUtils';
import {
  hasAllMcpPermissions,
  MCP_PERMISSION_GROUPS,
  selectAllMcpPermissions,
} from './mcpPermissionSelection';

interface ApiKey {
  id: number;
  keyId: string;
  name: string;
  permissions: string[];
  isActive: boolean;
  lastUsedAt: string | null;
  expiresAt: string | null;
  createdAt: string;
  notes: string | null;
  delegationEnabled: boolean;
  allowedDelegationDomains: string | null;
  allowedDelegateUserIds?: number[];
  delegationDomainCount: number;
}

interface CreateApiKeyRequest {
  name: string;
  permissions: string[];
  expiresAt?: string;
  notes?: string;
  delegationEnabled?: boolean;
  allowedDelegationDomains?: string;
}

const McpApiKeyManagement: React.FC = () => {
  const [apiKeys, setApiKeys] = useState<ApiKey[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showCreateForm, setShowCreateForm] = useState(false);
  const [createForm, setCreateForm] = useState<CreateApiKeyRequest>({
    name: '',
    permissions: [],
    expiresAt: '',
    notes: '',
    delegationEnabled: false,
    allowedDelegationDomains: ''
  });
  const [delegateIds, setDelegateIds] = useState('');
  const [newApiKey, setNewApiKey] = useState<string | null>(null);
  const [showInactive, setShowInactive] = useState(false);

  const permissionMeta: Record<string, { label: string; description: string; adminOnly?: boolean }> = {
    REQUIREMENTS_READ:    { label: 'Read Requirements',      description: 'View and search security requirements' },
    REQUIREMENTS_WRITE:   { label: 'Write Requirements',     description: 'Create and update security requirements' },
    REQUIREMENTS_DELETE:  { label: 'Delete Requirements',    description: 'Delete security requirements' },
    ASSESSMENTS_READ:     { label: 'Read Assessments',       description: 'View risk assessments and results' },
    ASSESSMENTS_EXECUTE:  { label: 'Execute Assessments',    description: 'Run new risk assessments' },
    ASSESSMENTS_WRITE:    { label: 'Write Assessments',      description: 'Create and update risk assessments' },
    FILES_READ:           { label: 'Read Files',             description: 'Download requirement files and attachments' },
    TAGS_READ:            { label: 'Read Tags',              description: 'View tags and categories' },
    ASSETS_READ:          { label: 'Read Assets',            description: 'View and search asset inventory' },
    ASSETS_WRITE:         { label: 'Write Assets',           description: 'Create and update assets in the inventory' },
    SCANS_READ:           { label: 'Read Scans',             description: 'View scan data and results' },
    VULNERABILITIES_READ: { label: 'Read Vulnerabilities',   description: 'View vulnerability information' },
    INTEGRATIONS_READ:    { label: 'Read Integrations',       description: 'View integration findings, runs, and health' },
    INTEGRATIONS_WRITE:   { label: 'Write Integrations',      description: 'Submit integration results for assigned subjects' },
    TRANSLATION_USE:      { label: 'Use Translations',       description: 'Translate requirements to different languages' },
    SYSTEM_INFO:          { label: 'System Information',     description: 'Access system information and statistics', adminOnly: true },
    USER_ACTIVITY:        { label: 'User Activity',          description: 'Monitor user activity and sessions', adminOnly: true },
    AUDIT_READ:           { label: 'Read Audit Logs',        description: 'View MCP server audit logs', adminOnly: true },
    WORKGROUPS_WRITE:     { label: 'Manage Workgroups',      description: 'Create, delete, and manage workgroup memberships', adminOnly: true },
    NOTIFICATIONS_SEND:   { label: 'Send Notifications',     description: 'Send admin summary emails and trigger notifications', adminOnly: true },
  };

  useEffect(() => {
    fetchApiKeys();
  }, [showInactive]);

  const fetchApiKeys = async () => {
    try {
      setLoading(true);
      // Authentication is handled via HttpOnly cookie (credentials: 'include')
      const url = showInactive ? '/api/mcp/admin/api-keys?include_inactive=true' : '/api/mcp/admin/api-keys';
      const response = await fetch(url, {
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        setApiKeys(data.apiKeys || []);
      } else {
        setError('Failed to fetch API keys');
      }
    } catch (err) {
      setError('Network error while fetching API keys');
    } finally {
      setLoading(false);
    }
  };

  const createApiKey = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null); // Clear previous errors

    if (!createForm.name.trim()) {
      setError('API key name is required');
      return;
    }

    if (createForm.permissions.length === 0) {
      setError('Please select at least one permission from the checkboxes above');
      return;
    }

    if (createForm.delegationEnabled) {
      if (!createForm.allowedDelegationDomains?.trim()) {
        setError('Allowed delegation domains are required when delegation is enabled');
        return;
      }
      // Validate domain format
      const domains = createForm.allowedDelegationDomains.split(',').map(d => d.trim()).filter(d => d);
      for (const domain of domains) {
        if (!domain.startsWith('@')) {
          setError(`Invalid domain format: '${domain}' (must start with @)`);
          return;
        }
        if (!domain.includes('.')) {
          setError(`Invalid domain format: '${domain}' (must contain a TLD)`);
          return;
        }
      }
    }

    const allowedDelegateUserIds = delegateIds.split(',').map(value => value.trim()).filter(Boolean).map(Number);
    if (allowedDelegateUserIds.length > 100 || allowedDelegateUserIds.some(value => !Number.isSafeInteger(value) || value <= 0)) {
      setError('Enter at most 100 positive user IDs, separated by commas.');
      return;
    }

    try {
      const requestBody = {
        name: createForm.name.trim(),
        permissions: createForm.permissions,
        expiresAt: createForm.expiresAt || undefined,
        notes: createForm.notes || undefined,
        delegationEnabled: createForm.delegationEnabled || false,
        allowedDelegateUserIds: createForm.delegationEnabled ? allowedDelegateUserIds : [],
        allowedDelegationDomains: createForm.delegationEnabled ? createForm.allowedDelegationDomains?.trim() : undefined
      };

      console.log('Creating API key with:', requestBody);

      // Authentication is handled via HttpOnly cookie (credentials: 'include')
      const response = await fetch('/api/mcp/admin/api-keys', {
        method: 'POST',
        credentials: 'include',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(requestBody)
      });

      console.log('Response status:', response.status);

      if (response.ok) {
        const data = await response.json();
        console.log('API key created:', data);
        setNewApiKey(data.apiKey);
        setShowCreateForm(false);
        setDelegateIds('');
        setCreateForm({ name: '', permissions: [], expiresAt: '', notes: '', delegationEnabled: false, allowedDelegationDomains: '' });
        fetchApiKeys();
        setError(null);
      } else {
        const errorData = await response.json().catch(() => ({ error: { message: 'Unknown error' } }));
        console.error('API key creation failed:', response.status, errorData);
        setError(errorData.error?.message || `Failed to create API key (${response.status})`);
      }
    } catch (err) {
      console.error('Network error:', err);
      setError('Network error while creating API key');
    }
  };

  const revokeApiKey = async (keyId: string, name: string) => {
    if (!confirm(`Are you sure you want to revoke the API key "${name}"? This action cannot be undone.`)) {
      return;
    }

    try {
      // Authentication is handled via HttpOnly cookie (credentials: 'include')
      const response = await fetch(`/api/mcp/admin/api-keys/${keyId}?reason=Revoked by user`, {
        method: 'DELETE',
        credentials: 'include'
      });

      if (response.ok) {
        fetchApiKeys();
        setError(null);
      } else {
        setError('Failed to revoke API key');
      }
    } catch (err) {
      setError('Network error while revoking API key');
    }
  };

  const handlePermissionChange = (permission: string, checked: boolean) => {
    setCreateForm(prev => ({
      ...prev,
      permissions: checked
        ? [...prev.permissions, permission]
        : prev.permissions.filter(p => p !== permission)
    }));
  };

  const handleAllPermissionsChange = (checked: boolean) => {
    setCreateForm(prev => ({
                  <div className="card border-info mb-3">
                    <div className="card-header bg-info bg-opacity-10">
                      <h6 className="mb-0">User Delegation</h6>
                    </div>
                    <div className="card-body">
                      <div className="form-check form-switch mb-3">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id="delegationEnabled"
                          checked={createForm.delegationEnabled || false}
                          onChange={(e) => setCreateForm(prev => ({
                            ...prev,
                            delegationEnabled: e.target.checked,
                            allowedDelegationDomains: e.target.checked ? prev.allowedDelegationDomains : ''
                          }))}
                        />
                        <label className="form-check-label" htmlFor="delegationEnabled">
                          Enable User Delegation
                        </label>
                      </div>
                      <div className="form-text mb-2">
                        When enabled, external tools can pass an authenticated user's email via the <code>X-MCP-User-Email</code> header.
                        Permissions will be the intersection of the user's roles and this API key's permissions.
                      </div>

                      {createForm.delegationEnabled && (
                        <div className="mb-0">
                          <label htmlFor="allowedDelegationDomains" className="form-label">
                            Allowed Email Domains *
                          </label>
                          <input
                            type="text"
                            className="form-control"
                            id="allowedDelegationDomains"
                            value={createForm.allowedDelegationDomains || ''}
                            onChange={(e) => setCreateForm(prev => ({ ...prev, allowedDelegationDomains: e.target.value }))}
                            placeholder="@company.com, @subsidiary.com"
                            required={createForm.delegationEnabled}
                          />
                          <div className="form-text">
                            Comma-separated list of allowed email domains (must start with @).
                            Delegated users must match a domain and be the key owner or explicitly listed below.
                          </div>
                          <label htmlFor="delegateUserIds" className="form-label mt-3">Additional delegated user IDs</label>
                          <input id="delegateUserIds" className="form-control" value={delegateIds}
                            onChange={event => setDelegateIds(event.target.value)} placeholder="12, 34" />
                          <div className="form-text">Comma-separated user IDs. Leave empty to permit only the key owner.</div>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => setShowCreateForm(false)}
                  >
                    Cancel
                  </button>
                  <button type="submit" className="btn btn-primary">
                    Create API Key
                  </button>
                </div>
              </form>
package com.secman.controller

import com.secman.service.*
import com.secman.domain.*
import com.secman.dto.mcp.*
import io.micronaut.http.HttpResponse
import io.micronaut.http.HttpStatus
import io.micronaut.http.annotation.*
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Inject
import jakarta.validation.Valid
import org.slf4j.LoggerFactory
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Administrative controller for MCP management operations.
 * Requires admin authentication via JWT.
 */
@Controller("/api/mcp/admin")
@Secured("ADMIN")
open class McpAdminController(
    @Inject private val authService: McpAuthenticationService,
    @Inject private val sessionService: McpSessionService,
    @Inject private val auditService: McpAuditService,
    @Inject private val toolPermissionService: McpToolPermissionService,
    @Inject private val userService: UserService,
    @Inject private val apiKeyRepository: com.secman.repository.McpApiKeyRepository
) {
    private val logger = LoggerFactory.getLogger(McpAdminController::class.java)

    // ===== API KEY MANAGEMENT =====

    /**
     * Create a new MCP API key.
     *
     * Supports user delegation:
     * - delegationEnabled: Enable delegation for this key
     * - allowedDelegationDomains: Required if delegation enabled (comma-separated, e.g. "@company.com")
     */
    @Post("/api-keys")
    open suspend fun createApiKey(
        @Valid @Body request: McpApiKeyCreateRequest,
        authentication: Authentication?
    ): HttpResponse<McpApiKeyCreateResponse> {
        return try {
            val userId = getUserIdFromAuth(authentication)
            if (userId == null) {
                return HttpResponse.status<McpApiKeyCreateResponse>(HttpStatus.UNAUTHORIZED)
                    .body(McpApiKeyCreateResponse(error = McpErrorResponse("AUTH_FAILED", "Invalid authentication")))
            }

            // Validate request
            val validationError = validateApiKeyRequest(request)
            if (validationError != null) {
                logger.debug("Request validation failed: {}", validationError)
                return HttpResponse.badRequest(
                    McpApiKeyCreateResponse(error = McpErrorResponse("INVALID_REQUEST", validationError))
                )
            }

            if (request.allowedDelegateUserIds.size > 100 || request.allowedDelegateUserIds.any { it <= 0 }) {
                return HttpResponse.badRequest(McpApiKeyCreateResponse(
                    error = McpErrorResponse("INVALID_REQUEST", "Specify at most 100 positive delegate user IDs")))
            }

            // Validate delegation configuration
            val delegationValidationError = validateDelegationConfig(request.delegationEnabled, request.allowedDelegationDomains)
            if (delegationValidationError != null) {
                logger.debug("Delegation validation failed: {}", delegationValidationError)
                return HttpResponse.badRequest(
                    McpApiKeyCreateResponse(error = McpErrorResponse("INVALID_DELEGATION_CONFIG", delegationValidationError))
                )
            }

            // Check for duplicate names
            if (apiKeyRepository.existsByUserIdAndName(userId, request.name)) {
                return HttpResponse.status<McpApiKeyCreateResponse>(HttpStatus.CONFLICT)
                    .body(McpApiKeyCreateResponse(error = McpErrorResponse("DUPLICATE_NAME", "An API key with this name already exists")))
            }

            // Parse permissions
            val permissions = request.permissions.map { McpPermission.valueOf(it) }.toSet()
            val expiresAt = request.expiresAt?.let { LocalDateTime.parse(it, DateTimeFormatter.ISO_LOCAL_DATE_TIME) }

            // Generate API key
            val keyPair = authService.generateApiKeyPair()

            // Create API key entity with delegation fields
            val apiKey = McpApiKey(
                keyId = keyPair.keyId,
                keyHash = keyPair.keyHash,
                name = request.name,
                userId = userId,
                permissions = McpApiKey.permissionsToString(permissions),
                expiresAt = expiresAt,
                notes = request.notes,
                delegationEnabled = request.delegationEnabled,
                allowedDelegationDomains = request.allowedDelegationDomains,
                allowedDelegateUserIds = request.allowedDelegateUserIds.sorted().joinToString(",")
            )

            // Save API key
            val savedApiKey = apiKeyRepository.save(apiKey)

            val response = McpApiKeyCreateResponse(
                keyId = keyPair.keyId,
                apiKey = keyPair.keySecret, // Only returned once!
                name = request.name,
                permissions = request.permissions,
                expiresAt = request.expiresAt,
                createdAt = LocalDateTime.now().format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
                delegationEnabled = savedApiKey.delegationEnabled,
                allowedDelegationDomains = savedApiKey.allowedDelegationDomains,
                allowedDelegateUserIds = request.allowedDelegateUserIds
            )

            logger.info("API key created: keyId={}, userId={}, name={}, delegationEnabled={}",
                       keyPair.keyId, userId, request.name, request.delegationEnabled)

            HttpResponse.status<McpApiKeyCreateResponse>(HttpStatus.CREATED).body(response)

        } catch (e: IllegalArgumentException) {
            HttpResponse.badRequest(
                McpApiKeyCreateResponse(error = McpErrorResponse("INVALID_PERMISSION", e.message ?: "Invalid permission"))
            )
        } catch (e: Exception) {
            logger.error("API key creation failed", e)
            HttpResponse.status<McpApiKeyCreateResponse>(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(McpApiKeyCreateResponse(error = McpErrorResponse("SYSTEM_ERROR", "API key creation failed")))
